      const toast = await page.evaluate("new Promise((resolve) => { const end=Date.now()+2000; const poll=()=>{ const item=document.querySelector('.vibeoffice-toast'); item ? resolve({role:item.getAttribute('role'),text:item.textContent.trim(),action:item.querySelector('button')?.textContent}) : Date.now()>end ? resolve(false) : setTimeout(poll,20); }; poll(); })");
